      BootSteps.begin('storage:sessionKeys');
      BootSteps.mark('storage:sessionKeys');
      expect(BootSteps.describe(), isNot(contains('in flight')));
    });

    test('describe caps the tail at the last six steps', () {
      for (var i = 0; i < 10; i++) {
        BootSteps.mark('step-$i');
