test('a successful restore stays silent while the user sits on home', () {
  fakeAsync((async) {
    final breadcrumbs = <String>[];
    final watchdog = watchdogWith(breadcrumbs);
    watchdog.install();
    async.elapse(const Duration(seconds: 3));
